const webhookData = input.webhookY6SI;

const body = webhookData?.[0]?.body;
const inserted = body?.Inserted?.[0];
const deleted = body?.Deleted?.[0];

// If there's no Deleted record, it's a new creation — not a loop
if (!deleted || !inserted) {
  return [{ isLoopEcho: false }];
}

// Fields to ignore when comparing (these change on any update)
const ignoreFields = [
  'LastModifiedDate',
  'LastModified',
  'LastActivity',
  'CompletedAt',
  'CreatedAt',
  'Timestamp',
  'tstamp',
  'NoteID',
  'UsrHSDealID'
];

// Normalize: remove ignored fields and HSDEALID from attributes
function normalize(record) {
  const clone = JSON.parse(JSON.stringify(record));

  // Remove top-level ignored fields (case-insensitive)
  for (const key of Object.keys(clone)) {
    if (ignoreFields.some(f => key.toLowerCase().includes(f.toLowerCase()))) {
      delete clone[key];
    }
  }

  return clone;
}

const normalizedInserted = normalize(inserted);
const normalizedDeleted = normalize(deleted);

const isLoopEcho = JSON.stringify(normalizedInserted) === JSON.stringify(normalizedDeleted);

return [{ isLoopEcho }];

