// Convert datetime string to epoch milliseconds (Long)
// Returns null for missing or invalid dates so the field can be omitted
function toISO(dateStr) {
  if (!dateStr) return null;
  const d = new Date(dateStr);
  return d.toISOString().split('T')[0] + 'T12:00:00.000Z';
}

// Determine if we should update the deal stage
function shouldUpdateStage(acumaticaStage, hubspotStageValue, hubspotOwnerId) {
  // If HubSpot deal has an owner assigned, protect against downgrades
  if (hubspotOwnerId && String(hubspotOwnerId).trim() !== '') {
    const normalizedAcuStage = acumaticaStage.trim().toUpperCase();
    const acumaticaRank = stageRankNormalized[normalizedAcuStage] || 0;
    // Convert HubSpot internal value back to name for rank comparison
    // If HubSpot stage is unrecognized (custom stage, different pipeline, etc.),
    // default to 999 to conservatively block the update and protect the deal
    const hubspotStageName = hubSpotStageToName[hubspotStageValue] || '';
    const hubspotRank = stageRank[hubspotStageName] || 999;
    // Only update if Acumatica stage rank is strictly greater
    return acumaticaRank > hubspotRank;
  }
  // No owner assigned - always allow stage update (existing behavior)
  return true;
}

