const mappedOwner = ownerToHubSpotNormalized[normalizedOwner] || '';

// Map stage name to HubSpot internal value (case-insensitive, trimmed)
const normalizedStage = acumaticaStage.trim().toUpperCase();
const mappedStage = stageToHubSpotNormalized[normalizedStage] || '';

const properties = {
  amount: record?.DetailTotal || '',
  dealname: safeString(record?.Description),
  hubspot_owner_id: mappedOwner,
  acumatica_opportunity_id: record?.OpportunityID || ''
};

// Only include date fields if they have valid values
const closedate = toISO(record?.EstimatedCloseDate);
if (closedate !== null) {
  properties.closedate = closedate;
}

const createdate = toISO(record?.DateCreated);
if (createdate !== null) {
  properties.createdate = createdate;
}

// Only include dealstage if we have a valid mapped stage and the update is allowed
if (mappedStage && shouldUpdateStage(acumaticaStage, currentHubspotStage, hubspotOwnerId)) {
  properties.dealstage = mappedStage;
}

return [{ properties }];

